package de.lazytv.pro.playlist;
import org.json.JSONException;import org.json.JSONObject;
public class Playlist {private String id,name;private PlaylistType type;private String url,username,password,macAddress;private long updatedAt;public Playlist(String id,String name,PlaylistType type,String url,String username,String password,String macAddress,long updatedAt){this.id=id;this.name=name;this.type=type;this.url=url;this.username=username;this.password=password;this.macAddress=macAddress;this.updatedAt=updatedAt;}public String getId(){return id;}public String getName(){return name;}public PlaylistType getType(){return type;}public String getUrl(){return url;}public String getUsername(){return username;}public String getPassword(){return password;}public String getMacAddress(){return macAddress;}public long getUpdatedAt(){return updatedAt;}public void setName(String v){name=v;}public void setType(PlaylistType v){type=v;}public void setUrl(String v){url=v;}public void setUsername(String v){username=v;}public void setPassword(String v){password=v;}public void setMacAddress(String v){macAddress=v;}public void touch(){updatedAt=System.currentTimeMillis();}public JSONObject toJson()throws JSONException{JSONObject o=new JSONObject();o.put("id",id);o.put("name",name);o.put("type",type.name());o.put("url",url);o.put("username",username);o.put("password",password);o.put("macAddress",macAddress);o.put("updatedAt",updatedAt);return o;}public static Playlist fromJson(JSONObject o)throws JSONException{return new Playlist(o.getString("id"),o.optString("name"),PlaylistType.valueOf(o.getString("type")),o.optString("url"),o.optString("username"),o.optString("password"),o.optString("macAddress"),o.optLong("updatedAt"));}}
